css:
#roulette-container {
  position: absolute;
  transform-origin: 50% 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 700px;
  height: 700px;
  user-select: none;
  pointer-events: auto;
}

#roulette-canvas {
  width: 700px;
  height: 700px;
  display: block;
  filter: drop-shadow(0px 18px 36px rgba(0,0,0,0.5));
}

#pointer-wrapper {
  position: absolute;
  top: -15px;
  left: 50%;
  width: 60px;
  height: 80px;
  margin-left: -30px;
  z-index: 10;
  transform-origin: 30px 15px;
}

render:
var p = ctx.progress;
var params = ctx.params;

ctx.root.style.backgroundColor = params.bg_color;

var container = ctx.root.querySelector('#roulette-container');
var canvas = ctx.root.querySelector('#roulette-canvas');
var pointerWrapper = ctx.root.querySelector('#pointer-wrapper');
var pointerSvg = ctx.root.querySelector('#pointer-svg');

if (!container || !canvas || !pointerWrapper || !pointerSvg) return;

container.style.left = params.pos_x + '%';
container.style.top = params.pos_y + '%';

var rawOptions = [params.opt_1, params.opt_2, params.opt_3, params.opt_4, params.opt_5, params.opt_6];
var activeOptions = [];
var originalIndices = [];

for (var i = 0; i < rawOptions.length; i++) {
  if (rawOptions[i] && rawOptions[i].trim() !== '') {
    activeOptions.push(rawOptions[i].trim());
    originalIndices.push(i + 1);
  }
}

if (activeOptions.length === 0) {
  activeOptions = ['SIN OPCIONES'];
  originalIndices = [1];
}

var numSectors = activeOptions.length;
var arcSize = (2 * Math.PI) / numSectors;

var targetActiveIndex = 0;
var targetWinningNum = Math.min(6, Math.max(1, Math.round(params.winning_index)));

var foundIdx = originalIndices.indexOf(targetWinningNum);
if (foundIdx !== -1) {
  targetActiveIndex = foundIdx;
} else {
  targetActiveIndex = 0;
}

pointerSvg.style.color = params.pointer_color;

var spinDur = Math.max(0.1, params.spin_duration);
var spinProgress = Math.min(1, Math.max(0, p / spinDur));

function easeOutQuart(t) {
  return 1 - Math.pow(1 - t, 4);
}

var targetSectorCenter = targetActiveIndex * arcSize + arcSize / 2;
var targetAngle = -Math.PI / 2 - targetSectorCenter;

var totalRotationRads = (params.spin_turns * 2 * Math.PI) + targetAngle;
while (totalRotationRads < params.spin_turns * 2 * Math.PI) {
  totalRotationRads += 2 * Math.PI;
}

var currentRotation = easeOutQuart(spinProgress) * totalRotationRads;

var pointerBounce = 0;
if (spinProgress > 0 && spinProgress < 1) {
  var normalizedAngle = (currentRotation + Math.PI / 2) % (2 * Math.PI);
  if (normalizedAngle < 0) normalizedAngle += 2 * Math.PI;

  var sectorPhase = (normalizedAngle % arcSize) / arcSize;
  if (sectorPhase > 0.82) {
    var hitIntensity = (1 - spinProgress);
    pointerBounce = -Math.sin((sectorPhase - 0.82) / 0.18 * Math.PI) * 22 * hitIntensity;
  }
}

pointerWrapper.style.transform = 'translate(-50%, 0) rotate(' + pointerBounce.toFixed(2) + 'deg)';
container.style.transform = 'translate(-50%, -50%) scale(' + params.scale + ')';

var ctx2d = canvas.getContext('2d');
var cx = 350;
var cy = 350;
var radius = 280;

ctx2d.clearRect(0, 0, 700, 700);

ctx2d.save();
ctx2d.beginPath();
ctx2d.arc(cx, cy, radius + 25, 0, 2 * Math.PI);
var outerGrad = ctx2d.createLinearGradient(0, 0, 700, 700);
outerGrad.addColorStop(0, '#3A3D40');
outerGrad.addColorStop(0.5, '#181A1C');
outerGrad.addColorStop(1, '#4E5256');
ctx2d.fillStyle = outerGrad;
ctx2d.fill();

ctx2d.beginPath();
ctx2d.arc(cx, cy, radius + 5, 0, 2 * Math.PI);
ctx2d.fillStyle = '#0D0E10';
ctx2d.fill();
ctx2d.restore();

ctx2d.save();
ctx2d.translate(cx, cy);
ctx2d.rotate(currentRotation);

var colors = [params.color_1, params.color_2, params.color_3, params.color_4];

for (var i = 0; i < numSectors; i++) {
  var startAngle = i * arcSize;
  var endAngle = startAngle + arcSize;

  ctx2d.beginPath();
  ctx2d.moveTo(0, 0);
  ctx2d.arc(0, 0, radius, startAngle, endAngle);
  ctx2d.closePath();

  ctx2d.fillStyle = colors[i % colors.length];
  ctx2d.fill();

  ctx2d.lineWidth = 4;
  ctx2d.strokeStyle = 'rgba(255, 255, 255, 0.3)';
  ctx2d.stroke();

  ctx2d.beginPath();
  ctx2d.arc(0, 0, radius, startAngle, endAngle);
  ctx2d.lineWidth = 10;
  ctx2d.strokeStyle = 'rgba(0, 0, 0, 0.15)';
  ctx2d.stroke();

  ctx2d.save();
  ctx2d.rotate(startAngle + arcSize / 2);
  ctx2d.textAlign = 'right';
  ctx2d.textBaseline = 'middle';
  ctx2d.fillStyle = params.text_color;
  ctx2d.font = '900 ' + Math.min(36, Math.max(18, 220 / numSectors)) + 'px ' + params.font_family;
  ctx2d.shadowColor = 'rgba(0,0,0,0.7)';
  ctx2d.shadowBlur = 6;
  ctx2d.shadowOffsetX = 2;
  ctx2d.shadowOffsetY = 2;

  var txt = activeOptions[i];
  if (txt.length > 14) txt = txt.substring(0, 12) + '..';

  ctx2d.fillText(txt, radius - 40, 0);
  ctx2d.restore();
}

for (var j = 0; j < numSectors; j++) {
  var pegAngle = j * arcSize;
  var px = Math.cos(pegAngle) * (radius - 12);
  var py = Math.sin(pegAngle) * (radius - 12);

  ctx2d.beginPath();
  ctx2d.arc(px, py, 7, 0, 2 * Math.PI);
  ctx2d.fillStyle = '#FFFFFF';
  ctx2d.shadowColor = '#000000';
  ctx2d.shadowBlur = 4;
  ctx2d.fill();

  ctx2d.beginPath();
  ctx2d.arc(px, py, 4, 0, 2 * Math.PI);
  ctx2d.fillStyle = '#888888';
  ctx2d.fill();
}

ctx2d.restore();

ctx2d.save();
ctx2d.beginPath();
ctx2d.arc(cx, cy, 45, 0, 2 * Math.PI);
var hubGrad = ctx2d.createRadialGradient(cx - 10, cy - 10, 5, cx, cy, 45);
hubGrad.addColorStop(0, '#FFFFFF');
hubGrad.addColorStop(0.5, '#D0D0D0');
hubGrad.addColorStop(1, '#707070');
ctx2d.fillStyle = hubGrad;
ctx2d.shadowColor = 'rgba(0,0,0,0.5)';
ctx2d.shadowBlur = 12;
ctx2d.fill();

ctx2d.beginPath();
ctx2d.arc(cx, cy, 32, 0, 2 * Math.PI);
ctx2d.fillStyle = '#181A1C';
ctx2d.fill();
ctx2d.restore();

if (params.show_lights) {
  var numLights = 16;
  var lightRadius = radius + 15;

  for (var k = 0; k < numLights; k++) {
    var lAngle = (k / numLights) * 2 * Math.PI;
    var lx = cx + Math.cos(lAngle) * lightRadius;
    var ly = cy + Math.sin(lAngle) * lightRadius;

    var lightOn = (Math.floor(p * 20) + k) % 2 === 0;

    ctx2d.save();
    ctx2d.beginPath();
    ctx2d.arc(lx, ly, 6, 0, 2 * Math.PI);
    ctx2d.fillStyle = lightOn ? '#FFCC00' : '#443300';
    if (lightOn) {
      ctx2d.shadowColor = '#FFCC00';
      ctx2d.shadowBlur = 10;
    }
    ctx2d.fill();
    ctx2d.restore();
  }
}
